-- Baureihentext für SCALA2 (27.10.2026)
--
-- SCALA2 hat in den Grundfos-Daten weder Produktgruppe noch DB_PGD-Text (nur die Vorgänger-Baureihe „SCALA“).
-- shop_produkt (0046) liest für solche Pumpen den Bereich SHOP_SERIE mit dem ersten Teil der Typbezeichnung als Schlüssel.
-- Eigene Formulierung nach den Produktmerkmalen, herkunft = 'maschinell' (Grundfos-Texte bleiben unberührt).

insert into pim.uebersetzung (bereich, schluessel, sprache, text, herkunft)
select 'SHOP_SERIE', 'SCALA2', s, t, 'maschinell'
  from (values
  ('de', 'Grundfos SCALA2 ist eine vollintegrierte, selbstansaugende Druckerhöhungspumpe mit Konstantdruckregelung für die häusliche Wasserversorgung in Ein- und Zweifamilienhäusern. Pumpe, Motor, Regelung, Druckbehälter und Rückschlagventil sind in einer kompakten, leisen Einheit vereint; ein Trockenlaufschutz ist integriert.'),
  ('en', 'Grundfos SCALA2 is a fully integrated, self-priming booster pump with constant-pressure control for domestic water supply in one- and two-family houses. Pump, motor, controller, pressure tank and non-return valve are combined in one compact, quiet unit; dry-running protection is built in.'),
  ('fr', 'Grundfos SCALA2 est une pompe de surpression auto-amorçante entièrement intégrée, à régulation de pression constante, pour l''alimentation en eau domestique des maisons individuelles et bifamiliales. Pompe, moteur, régulation, réservoir sous pression et clapet anti-retour sont réunis dans une unité compacte et silencieuse ; la protection contre la marche à sec est intégrée.'),
  ('it', 'Grundfos SCALA2 è una pompa di pressurizzazione autoadescante completamente integrata, con regolazione a pressione costante, per l''approvvigionamento idrico domestico in case mono e bifamiliari. Pompa, motore, regolazione, serbatoio a pressione e valvola di non ritorno sono riuniti in un''unità compatta e silenziosa; la protezione contro la marcia a secco è integrata.'),
  ('nl', 'Grundfos SCALA2 is een volledig geïntegreerde, zelfaanzuigende drukverhogingspomp met constante-drukregeling voor de huishoudelijke watervoorziening in een- en tweegezinswoningen. Pomp, motor, regeling, drukvat en terugslagklep zijn gecombineerd in één compacte, stille unit; drooglopbeveiliging is ingebouwd.'),
  ('pl', 'Grundfos SCALA2 to w pełni zintegrowana, samozasysająca pompa do podnoszenia ciśnienia z regulacją stałego ciśnienia, przeznaczona do zaopatrzenia w wodę domów jedno- i dwurodzinnych. Pompa, silnik, sterownik, zbiornik ciśnieniowy i zawór zwrotny tworzą jedną kompaktową, cichą jednostkę; zabezpieczenie przed suchobiegiem jest wbudowane.'),
  ('es', 'Grundfos SCALA2 es una bomba de presurización autocebante totalmente integrada, con control de presión constante, para el suministro de agua doméstico en viviendas unifamiliares y bifamiliares. Bomba, motor, control, depósito de presión y válvula de retención se combinan en una unidad compacta y silenciosa; la protección contra marcha en seco está integrada.'),
  ('pt', 'A Grundfos SCALA2 é uma bomba de pressurização autoferrante totalmente integrada, com controlo de pressão constante, para o abastecimento de água doméstico em moradias uni e bifamiliares. Bomba, motor, controlador, depósito de pressão e válvula de retenção estão combinados numa unidade compacta e silenciosa; a proteção contra funcionamento a seco está integrada.'),
  ('sv', 'Grundfos SCALA2 är en helt integrerad, självsugande tryckstegringspump med konstanttrycksreglering för hushållets vattenförsörjning i en- och tvåfamiljshus. Pump, motor, styrning, tryckkärl och backventil är samlade i en kompakt och tyst enhet; torrkörningsskydd är inbyggt.'),
  ('da', 'Grundfos SCALA2 er en fuldt integreret, selvansugende trykforøgerpumpe med konstanttryksregulering til husholdningens vandforsyning i en- og tofamiliehuse. Pumpe, motor, styring, trykbeholder og kontraventil er samlet i én kompakt og støjsvag enhed; tørløbsbeskyttelse er indbygget.'),
  ('fi', 'Grundfos SCALA2 on täysin integroitu, itseimevä paineenkorotuspumppu, jossa on vakiopainesäätö, kotitalouksien vedensyöttöön omakoti- ja paritaloissa. Pumppu, moottori, säädin, painesäiliö ja takaiskuventtiili on yhdistetty yhdeksi kompaktiksi ja hiljaiseksi yksiköksi; kuivakäyntisuojaus on sisäänrakennettu.'),
  ('nb', 'Grundfos SCALA2 er en fullt integrert, selvsugende trykkøkningspumpe med konstanttrykksregulering for husholdningens vannforsyning i ene- og tomannsboliger. Pumpe, motor, styring, trykktank og tilbakeslagsventil er samlet i én kompakt og stillegående enhet; tørrkjøringsvern er innebygd.'),
  ('cs', 'Grundfos SCALA2 je plně integrované, samonasávací čerpadlo pro zvyšování tlaku s regulací na konstantní tlak, určené pro domácí zásobování vodou v rodinných a dvougeneračních domech. Čerpadlo, motor, řízení, tlaková nádoba a zpětný ventil tvoří jednu kompaktní a tichou jednotku; ochrana proti chodu nasucho je integrována.'),
  ('sk', 'Grundfos SCALA2 je plne integrované, samonasávacie čerpadlo na zvyšovanie tlaku s reguláciou na konštantný tlak, určené na domáce zásobovanie vodou v rodinných a dvojgeneračných domoch. Čerpadlo, motor, riadenie, tlaková nádoba a spätný ventil tvoria jednu kompaktnú a tichú jednotku; ochrana proti chodu nasucho je integrovaná.'),
  ('hu', 'A Grundfos SCALA2 teljesen integrált, önfelszívó nyomásfokozó szivattyú állandó nyomású szabályozással, egy- és kétcsaládos házak háztartási vízellátásához. A szivattyú, a motor, a vezérlés, a nyomástartály és a visszacsapó szelep egyetlen kompakt, csendes egységet alkot; a szárazonfutás elleni védelem beépített.'),
  ('ro', 'Grundfos SCALA2 este o pompă de ridicare a presiunii complet integrată, autoamorsantă, cu reglare la presiune constantă, pentru alimentarea casnică cu apă în locuințe uni- și bifamiliale. Pompa, motorul, controlerul, vasul de presiune și clapeta de reținere sunt reunite într-o unitate compactă și silențioasă; protecția la funcționarea în gol este integrată.'),
  ('bg', 'Grundfos SCALA2 е напълно интегрирана, самозасмукваща помпа за повишаване на налягането с регулиране на постоянно налягане за битово водоснабдяване в еднофамилни и двуфамилни къщи. Помпа, двигател, управление, разширителен съд и възвратен клапан са обединени в един компактен и тих агрегат; защитата от работа на сухо е вградена.'),
  ('hr', 'Grundfos SCALA2 potpuno je integrirana, samousisna crpka za povišenje tlaka s regulacijom konstantnog tlaka za kućnu opskrbu vodom u obiteljskim kućama. Crpka, motor, upravljanje, tlačna posuda i nepovratni ventil objedinjeni su u jednu kompaktnu i tihu jedinicu; zaštita od rada na suho je ugrađena.'),
  ('sl', 'Grundfos SCALA2 je popolnoma integrirana, samosesalna črpalka za dvig tlaka z regulacijo konstantnega tlaka za oskrbo gospodinjstev z vodo v eno- in dvodružinskih hišah. Črpalka, motor, krmiljenje, tlačna posoda in protipovratni ventil so združeni v eno kompaktno in tiho enoto; zaščita pred suhim tekom je vgrajena.'),
  ('el', 'Η Grundfos SCALA2 είναι μια πλήρως ενσωματωμένη, αυτόματης αναρρόφησης αντλία αύξησης πίεσης με έλεγχο σταθερής πίεσης για την οικιακή ύδρευση σε μονοκατοικίες και διπλοκατοικίες. Αντλία, κινητήρας, ελεγκτής, δοχείο πίεσης και βαλβίδα αντεπιστροφής συνδυάζονται σε μία συμπαγή και αθόρυβη μονάδα· η προστασία από ξηρή λειτουργία είναι ενσωματωμένη.'),
  ('et', 'Grundfos SCALA2 on täielikult integreeritud, isevalguv rõhutõstepump konstantse rõhu reguleerimisega ühe- ja kahepereelamute olmeveevarustuseks. Pump, mootor, juhtseade, rõhupaak ja tagasilöögiklapp on ühendatud üheks kompaktseks ja vaikseks seadmeks; kuivkäigukaitse on sisseehitatud.'),
  ('lv', 'Grundfos SCALA2 ir pilnībā integrēts, pašuzsūcošs spiediena paaugstināšanas sūknis ar pastāvīga spiediena regulēšanu mājsaimniecību ūdensapgādei vienģimenes un divģimeņu mājās. Sūknis, motors, vadība, spiedtvertne un pretvārsts ir apvienoti vienā kompaktā un klusā iekārtā; aizsardzība pret darbību bez ūdens ir iebūvēta.'),
  ('lt', 'Grundfos SCALA2 – visiškai integruotas, savisiurbis slėgio didinimo siurblys su pastovaus slėgio reguliavimu, skirtas buitiniam vandens tiekimui vienbučiuose ir dvibučiuose namuose. Siurblys, variklis, valdiklis, slėgio indas ir atbulinis vožtuvas sujungti į vieną kompaktišką ir tylų įrenginį; apsauga nuo sausosios eigos yra integruota.')
  ) v(s, t)
on conflict (bereich, sprache, schluessel) do nothing;
